def transform(grid):
    h, w = len(grid), len(grid[0])
    # Separator divides two noisy patterns; output the color that is uniform
    # in the pattern on each side, filling the separator-side dimensions.
    c = next(j for j in range(w) if all(grid[i][j] == 0 for i in range(h)))
    counts_left, counts_right = {}, {}
    for i in range(h):
        for j in range(c):
            counts_left[grid[i][j]] = counts_left.get(grid[i][j], 0) + 1
        for j in range(c + 1, w):
            counts_right[grid[i][j]] = counts_right.get(grid[i][j], 0) + 1
    # Color appearing most often across both regions is the background color.
    totals = {}
    for d in (counts_left, counts_right):
        for color, n in d.items():
            totals[color] = totals.get(color, 0) + n
    color = max(totals, key=totals.get)
    return [[color] * c for _ in range(h)]
